INSERT INTO provider_template (tpl_id, name, category, caps_json, instance_params_json, sync_json, async_json, upload_json, clone_json, ord)
VALUES ('deepseek-chat', 'openai', 'llm', '{"modes":"sync"}', '[{"key":"baseUrl","label":"服务地址","valueType":"string","defaultValue":"https://api.deepseek.com"},{"key":"apiKey","label":"API Key","valueType":"secret"},{"key":"timeoutMs","label":"单次超时 ms","valueType":"number","defaultValue":60000}]', '{"submit":{"path":"${baseUrl}/chat/completions","method":"POST","headers":{"Content-Type":"application/json","Authorization":"Bearer ${apiKey}"},"requestParams":[{"key":"model","label":"模型","valueType":"enum","options":["deepseek-flash","deepseek-v4-pro"],"defaultValue":"deepseek-flash"},{"key":"reasoningEffort","label":"思考强度","valueType":"enum","options":["none","low","high","max"]},{"key":"thinking","label":"深度思考","valueType":"enum","options":["enabled","disabled"]},{"key":"temperature","label":"温度","valueType":"number","defaultValue":1,"min":0,"max":2,"step":0.1},{"key":"maxTokens","label":"最大输出 token","valueType":"number","defaultValue":200000},{"key":"systemPrompt","label":"系统提示词","valueType":"text"},{"key":"userPrompt","label":"用户提示词","valueType":"text"}],"body":{"model":"${model}","messages":[{"role":"system","content":"${systemPrompt}"},{"role":"user","content":"${userPrompt}"}],"stream":false,"reasoning_effort":"${reasoningEffort}","thinking":{"type":"${thinking}"},"temperature":"${temperature}","max_tokens":"${maxTokens}"},"outputs":{"content":"choices[0].message.content","errorCode":"error.code","error":"error.message"}}}', NULL, NULL, NULL, 0)
