sk_id","errorCode":"code","error":"message"}},"query":{"path":"${baseUrl}/tasks/${taskId}","method":"GET","headers":{"Authorization":"Bearer ${apiKey}"},"artifactForm":"url","outputs":{"status":"output.task_status","artifact":"output.choices[0].message.content[0].image","errorCode":"code","error":"message"},"successValues":["SUCCEEDED"],"failureValues":["FAILED","CANCELED","UNKNOWN"]}}', NULL, NULL, 1)
