VALUES ('qwen-tts', '千问 TTS', 'tts', '{"modes":"sync","clone":true,"cloneVia":"base64"}', '[{"key":"baseUrl","label":"服务地址","valueType":"string","defaultValue":"https://maas.qianwenaiapi.com/api/v1"},{"key":"apiKey","label":"API Key","valueType":"secret"},{"key":"timeoutMs","label":"单次超时 ms","valueType":"number","defaultValue":60000}]', '{"submit":{"path":"${baseUrl}/services/aigc/multimodal-generation/generation","method":"POST","headers":{"Content-Type":"application/json","Authorization":"Bearer ${apiKey}"},"requestParams":[{"key":"model","label":"模型","valueType":"enum","options":["qwen3-tts-flash","qwen3-tts-vc-2026-01-22"],"defaultValue":"qwen3-tts-flash"},{"key":"languageType","label":"语种","valueType":"enum","options":["Chinese","English","Auto"],"defaultValue":"Chinese"},{"key":"text","label":"合成文本","valueType":"text"},{"key":"voice","label":"音色 ID","valueType":"string","defaultValue":"Ethan"}],"body":{"model":"${model}","input":{"text":"${text}","voice":"${voice}","language_type":"${languageType}"}},"artifactForm":"url","outputs":{"artifact":"output.audio.url","errorCode":"code","error":"message"}}}', NULL, NULL, '{"path":"${baseUrl}/services/audio/tts/customization","method":"POST","headers":{"Content-Type":"application/json","Authorization":"Bearer ${apiKey}"},"requestParams":[{"key":"model","label":"复刻目标模型（须与合成同款）","valueType":"enum","options":["qwen3-tts-vc-2026-01-22"],"defaultValue":"qwen3-tts-vc-2026-01-22"},{"key":"preferredName","label":"音色名","valueType":"string","defaultValue":"mapvideo"}],"body":{"model":"qwen-voice-enrollment","input":{"action":"create","target_model":"${model}","preferred_name":"${preferredName}","audio":{"data":"${voiceData}"}}},"outputs":{"voiceId":"output.voice","errorCode":"code","error":"message"}}', 2)
